def esc(t):return html.escape(str(t),quote=True)
def asset(slug):return '/assets/images/'+slug+'.webp'
def btn(text,href,outline=False):return f'<a class="btn {"btn-outline" if outline else "btn-solid"}" href="{esc(href)}">{esc(text)} <span aria-hidden="true">↗</span></a>'
def img(slug,alt='',cls=''):
 m=next((x for x in manifest if x['name']==slug+'.webp'),None)
 attrs = ("width=%s height=%s" % (m["width"], m["height"])) if m else ""
 return f'<img class="{cls}" src="{asset(slug)}" alt="{esc(alt or slug.replace("-"," "))}" loading="lazy" decoding="async" {attrs}>'
nav=[('Services','/services/'),('Portfolio','/portfolio/'),('For business','/industries/'),('Locations','/areas/'),('Guides','/guides/'),('About','/about/')]
def header():
 return '''<a class="skip" href="#main">Skip to content</a><div class="topstrip"><span>Property media for Melbourne’s south-east</span><span>Established 2006 · Casey & Cardinia</span></div><header class="site-header"><div class="nav-wrap"><a class="brand" href="/" aria-label="Property Snaps home"><span class="brand-mark" aria-hidden="true"><i></i><i></i><i></i><i></i></span><span>PROPERTY <b>SNAPS</b><small>REAL ESTATE MEDIA</small></span></a><button class="menu-toggle" aria-expanded="false" aria-controls="nav" aria-label="Toggle navigation"><span></span><span></span><span></span></button><nav id="nav" class="nav" aria-label="Main navigation">'''+''.join(f'<a href="{h}">{t}</a>' for t,h in nav)+'''<a class="nav-cta" href="/contact/">Request a quote ↗</a></nav></div></header>'''
def footer():
 return f'''<footer class="footer"><div class="container"><div class="footer-top"><div><a class="brand brand-light" href="/">PROPERTY <b>SNAPS</b><small>REAL ESTATE MEDIA</small></a><p>Thoughtful property photography and marketing media, proudly working across Casey and Cardinia since 2006.</p></div><div><h3>Explore</h3><a href="/services/">Services</a><a href="/portfolio/">Portfolio</a><a href="/areas/">Service areas</a><a href="/guides/">Free guides</a><a href="/faq/">FAQ</a><a href="/privacy/">Privacy</a></div><div><h3>For your industry</h3><a href="/industries/real-estate-agents/">Real estate agents</a><a href="/industries/builders-and-trades/">Builders & trades</a><a href="/industries/pool-and-landscape-builders/">Pools & landscaping</a><a href="/industries/property-developers/">Developers</a></div><div><h3>Start a project</h3><a href="/contact/">Request a quote</a><a href="tel:+61408559555">{phone}</a><a href="mailto:{contact}">{contact}</a></div></div><div class="footer-bottom">© 2026 Property Snaps · Property media since 2006 <span>Melbourne south-east · Casey · Cardinia</span></div></div></footer>'''
def layout(title,description,body,path='/',hero=None,js=''):
 canonical=base+path
 ld={'@context':'https://schema.org','@type':'ProfessionalService','name':'Property Snaps','url':base+'/','foundingDate':'2006','areaServed':[{'@type':'Place','name':i+', Victoria, Australia'} for i in ['Casey','Cardinia','Cranbourne','Berwick','Pakenham','Officer']],'description':'Photography, drone, floor plans, video and marketing media for Melbourne south-east.'}
 return f'''<!doctype html><html lang="en-AU"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)} | Property Snaps</title><meta name="description" content="{esc(description)}"><meta name="theme-color" content="#183b3a"><link rel="canonical" href="{canonical}"><meta property="og:title" content="{esc(title)} | Property Snaps"><meta property="og:description" content="{esc(description)}"><meta property="og:type" content="website"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{base}{asset(hero or 'twilight-pool')}"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@400;500;600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="/assets/site.css"><script type="application/ld+json">{json.dumps(ld)}</script></head><body>{header()}<main id="main">{body}</main>{footer()}<script src="/assets/site.js" defer></script>{js}</body></html>'''
def write(path,code):
 p=R/path.lstrip('/')/'index.html' if path not in ['/','/index.html'] else R/'index.html';p.parent.mkdir(parents=True,exist_ok=True);p.write_text(code,encoding='utf8')
def kicker(t):return f'<span class="eyebrow">{esc(t)}</span>'
def section_heading(k,h,p=''):
 return f'<div class="section-heading">{kicker(k)}<h2>{h}</h2>{f"<p>{p}</p>" if p else ""}</div>'
def hero(k,t,desc,photo,buttons=''):
 return f'<section class="page-hero"><div class="page-hero-photo">{img(photo,t)}</div><div class="page-hero-overlay"></div><div class="container page-hero-content">{kicker(k)}<h1>{t}</h1><p>{desc}</p><div class="button-row">{buttons or btn("Discuss your project","/contact/")}</div></div></section>'
def split(k,t,txt,photo,reverse=False,cta=None):
 return f'<section class="section"><div class="container split {"reverse" if reverse else ""}"><div class="split-media">{img(photo,t)}</div><div class="split-copy">{kicker(k)}<h2>{t}</h2><p>{txt}</p>{btn("Explore the service",cta) if cta else btn("Request a quote","/contact/")}</div></div></section>'
def image_grid(items=None,limit=None):
 its=(items or manifest)[:limit] if limit else (items or manifest)
 return '<div class="portfolio-grid">'+''.join(f'<a class="gallery-item" href="/portfolio/#gallery" data-cat="{esc(x["category"])}"><figure><img src="/assets/images/{x["name"]}" loading="lazy" decoding="async" alt="{esc(x["title"])}"><figcaption><span>{esc(x["category"])}</span><strong>{esc(x["title"])}</strong></figcaption></figure></a>' for x in its)+'</div>'

def cards(items,category):
 return '<div class="service-grid">'+''.join(f'<a class="service-card" href="/{category}/{s}/">{img(info[4] if category=="services" else info[3],info[0])}<div class="service-card-copy">{kicker(info[3] if category=="services" else "Industry media")}<h3>{esc(info[0])}</h3><p>{esc(info[2][:135])}…</p><span class="inline-link">Discover more ↗</span></div></a>' for s,info in items.items())+'</div>'

