ar+='<section class="end-cta"><div class="container"><h2>Your suburb not on the list?</h2><p>Send us your location and scope and we can discuss availability.</p>'+btn('Contact Property Snaps','/contact/')+'</div></section>'
write('/areas/',layout('Property Photography Service Areas | Casey & Cardinia','Local property photography, drone and floor plan services in Cranbourne, Berwick, Clyde North, Pakenham, Officer and surrounding Casey and Cardinia suburbs.',ar,'/areas/','parkland-aerial'))
for city in areas:
 slug=city.lower().replace(' ','-');focus,paragraph=area_focus[city]
 body=hero('Serving '+city,'Property photography in '+city+'.',paragraph,'modern-home-daylight',btn('Enquire about a shoot','/contact/')+btn('View all services','/services/',True))
 body+='<section class="section"><div class="container two-col-content"><div>'+kicker('Local coverage')+'<h2>'+esc(focus)+'</h2><p>Property Snaps provides photography and marketing media for residential agents, builders and property professionals working in '+city+' and neighbouring Casey/Cardinia areas.</p><p>'+esc(paragraph)+' Every project is scoped individually based on the property, deliverables and scheduling.</p></div><div class="detail-panel"><h3>Popular services</h3><ul class="checklist"><li>Real estate listing photography</li><li>Drone and aerial imagery</li><li>Measured floor plans and 3D views</li><li>Twilight photography and property video</li></ul>'+btn('Request availability','/contact/')+'</div></div></section>'
 body+='<section class="section section-soft"><div class="container">'+section_heading('Working around '+city,'Useful imagery for every campaign.')+image_grid(manifest[3:7])+'</div></section>'
 body+='<section class="end-cta"><div class="container"><h2>Have a '+city+' property to market?</h2>'+btn('Request a tailored quote','/contact/')+'</div></section>'
 write('/areas/'+slug+'/',layout('Property Photography '+city+' | Drone & Floor Plans','Real estate photography, drone photos, measured floor plans and property marketing for agents and builders in '+city+', Melbourne south-east.',body,'/areas/'+slug+'/','modern-home-daylight'))
# guides
form='''<form class="lead-form" name="guide-download" method="POST" data-netlify="true" netlify-honeypot="bot-field" action="/downloads/"><input type="hidden" name="form-name" value="guide-download"><p class="hidden"><label>Leave this blank <input name="bot-field"></label></p><div class="field-pair"><label>Full name <input name="name" autocomplete="name" required placeholder="Your name"></label><label>Work email <input name="email" type="email" autocomplete="email" required placeholder="you@agency.com.au"></label></div><div class="field-pair"><label>Company <input name="company" autocomplete="organization" placeholder="Agency or business"></label><label>Your industry <select name="industry" required><option value="">Select one</option><option>Real estate</option><option>Builder / trade</option><option>Pools / landscaping</option><option>Developer</option><option>Other</option></select></label></div><label class="check-consent"><input type="checkbox" name="follow_up_consent" value="yes"> I’m happy for Property Snaps to contact me about my enquiry. (Optional)</label><button type="submit" class="btn btn-solid">Access the service guides ↗</button><p class="form-note">We use your details to provide the guides. Optional follow-up is only with your permission.</p></form>'''
guides=hero('Free service guides','Plan the shoot. Build a better campaign.','Download our newly updated Property Snaps guides for agents, builders and pool businesses. No historical pricing tables; tell us about your project for a current quote.','kitchen-detail',btn('Go to download form','#download-form'))
guides+='<section class="section"><div class="container"><div class="guides-grid">'+''.join(f'<article class="guide-card">{img(photo,title)}{kicker("2026 EDITION")}<h3>{title}</h3><p>{desc}</p><a href="#download-form" class="inline-link">Get guide ↗</a></article>' for title,desc,photo in [('Real Estate Media Guide','Photography, drone, measured plans, video and listing campaign options.','listing-daylight'),('Builder & Trade Media Guide','Photography and portfolio media for builders, designers and specialist trades.','architectural-exterior'),('Pool & Outdoor Media Guide','Daytime, twilight and aerial content for pool and landscape businesses.','twilight-pool')])+'</div></div></section>'
guides+='<section class="section section-soft" id="download-form"><div class="container form-split"><div>'+kicker('Your downloadable guides')+'<h2>Three guides. One simple form.</h2><p>Enter your details to access all three professionally designed PDFs. We keep current service pricing off public documents and quote by brief.</p>'+img('open-plan-living','Contemporary property interior')+'</div>'+form+'</div></section>'
write('/guides/',layout('Free Property Media Guides for Agents and Builders','Download Property Snaps service guides for real estate agents, builders, pool companies and landscape businesses. No public pricing.',guides,'/guides/','kitchen-detail'))
links=[('Real Estate Media Guide','property-snaps-real-estate-guide-2026.pdf'),('Builder & Trade Media Guide','property-snaps-builders-guide-2026.pdf'),('Pool & Outdoor Media Guide','property-snaps-pools-guide-2026.pdf')]
down='<section class="thankyou"><div class="container narrow">'+kicker('Resources')+'<h1>Your guides are ready.</h1><p>Download any or all of the Property Snaps service guides. We can also help with a custom quote for your next project.</p><div class="download-list">'+''.join(f'<a download href="/assets/guides/{f}"><span>{n}</span><strong>Download PDF ↓</strong></a>' for n,f in links)+'</div>'+btn('Request a quote','/contact/')+'</div></section>'
write('/downloads/',layout('Download Property Snaps Service Guides','Download the updated Property Snaps 2026 guides for real estate, builders and pool businesses.',down,'/downloads/','listing-daylight'))
