# additional practical pages and privacy policy
privacy=hero('How we use your information','Privacy & enquiries.','Property Snaps collects only the information needed to answer your enquiry and supply requested resources.','open-plan-living',btn('Contact us','/contact/'))
privacy+='<section class="section"><div class="container editorial-about"><h2>Your information</h2><p>When you submit an enquiry or request guides, we may collect your name, work email, telephone number, company, suburb, service requirements and the message you provide. We use this information to answer your request, prepare quotes, arrange service and deliver requested guides.</p><h3>Contact preferences</h3><p>Guide downloads include an optional checkbox for future contact. We will not treat a guide download as permission to send unrelated marketing without that choice.</p><h3>Where information goes</h3><p>Forms on this website are processed using Netlify Forms. Information may be handled by Netlify or relevant service providers to operate the site. Please avoid sending sensitive documents or personal records through the standard enquiry form.</p><h3>Your questions</h3><p>To ask about personal information submitted through the website, request correction or deletion, contact Property Snaps using the contact details on our contact page.</p><h3>Website analytics</h3><p>This launch version does not install third-party advertising trackers. External font resources may be requested to display the site styling. If tracking systems are added later this page should be updated.</p></div></section>'
write('/privacy/',layout('Privacy and Personal Information','How Property Snaps handles website enquiries, service-guide requests and contact information.',privacy,'/privacy/','open-plan-living'))
faq_items=[('What areas do you service?','We focus on Casey and Cardinia, including Cranbourne, Berwick, Narre Warren, Pakenham, Officer, Clyde and neighbouring suburbs. Ask about other locations.'),('Can I book photography and a floor plan together?','Yes. We can scope photography, aerial images, floor plans and video as a coordinated property-media brief.'),('Do you offer twilight photography?','Yes. True twilight sessions suit properties with exterior lighting, quality landscaping and strong street appeal. Availability depends on weather, access and timing.'),('Can you provide measured floor plans or CAD?','Measured marketing floor plans, 2D drawings, 3D perspectives and CAD-style support may be available by agreed scope. Marketing plans are not land surveys or statutory certification.'),('Do you photograph finished builds or pools?','Yes. Property Snaps creates photography and media for home builders, designers, specialist trades, pool builders and landscape companies.'),('Can you fly a drone at any property?','Drone services depend on weather, permission, nearby airspace and applicable regulations. We check suitability as part of the brief.'),('Do you publish service pricing?','No. We quote by property type, access requirements, location and deliverables so you receive an accurate current price.'),('How do I request a quote?','Use the enquiry form and include the property suburb, timeline and services required. We will respond to discuss the scope.')]
faq=hero('Frequently asked questions','Practical answers before the shoot.','Clear information for agents, builders and property managers planning photography, drone, measured plans and video.','listing-daylight')
faq+='<section class="section"><div class="container editorial-about"><div class="faq-list">'+''.join(f'<details><summary>{esc(q)}</summary><p>{esc(a)}</p></details>' for q,a in faq_items)+'</div></div></section>'
faq+='<section class="end-cta"><div class="container"><h2>Have another question?</h2>'+btn('Ask about your project','/contact/')+'</div></section>'
write('/faq/',layout('Real Estate Photography FAQ | Casey & Cardinia','Answers about Property Snaps photography, drone flights, CAD floor plans, service areas, pricing and booking.',faq,'/faq/','listing-daylight', '<script type="application/ld+json">'+json.dumps({'@context':'https://schema.org','@type':'FAQPage','mainEntity':[{'@type':'Question','name':q,'acceptedAnswer':{'@type':'Answer','text':a}} for q,a in faq_items]})+'</script>'))
prepare=hero('Guide for property owners','Preparing your home for photography.','A few practical steps before the shoot help produce stronger, more consistent listing media.','interior-wideangle')
prepare+='<section class="section"><div class="container two-col-content"><div>'+section_heading('Before the appointment','The small details that matter.')+'<p>Clean countertops and mirrors, open blinds, turn on appropriate lights, tidy garden edges, move bins and cars from hero angles, and secure pets. The photographer can then focus on capturing the property.</p><p>If your campaign includes twilight photography, check that external and garden lighting is functioning before the appointment.</p></div><div class="detail-panel"><h3>Quick preparation checklist</h3><ul class="checklist"><li>Remove personal paperwork and clutter</li><li>Clear kitchen benches and bathroom surfaces</li><li>Make beds and straighten soft furnishings</li><li>Tidy lawns, paving and outdoor entertaining areas</li><li>Arrange access to all rooms</li><li>Advise us of special features or restricted access</li></ul></div></div></section>'
write('/resources/prepare-for-photography/',layout('How to Prepare a House for Real Estate Photography','Practical pre-shoot checklist for agents and vendors in Casey and Cardinia: interiors, landscaping, lighting and access.',prepare,'/resources/prepare-for-photography/','interior-wideangle'))
